                new { D = new DateTime(2012, 1, 1), T = "Обирає фах", Desc = "Коли прийшов час обирати фах, Роман зупиняє свій вибір на юридичному та вступає до Фінансово-правового коледжу в Києві.", SId = 2, P = DateViewPattern.Year },
