                new { D = new DateTime(2019, 1, 1), T = "Погрози", Desc = "Через погрози фізичною розправою та викраденням, про які Роман заявив у жовтні 2019-го, йому доводиться деякий час переховуватися.", SId = 2, P = DateViewPattern.Year },
